import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Register-blocked tiled direct 2D convolution (NCHW, contiguous, float32).
// Each CTA computes a 16x64 output tile for 4 consecutive output channels (OC-blocked); each of 256 threads computes 4x4 outputs.
// Input tiles (halo included) are staged cooperatively in shared memory per input channel.
.extern .shared .align 4 .b8 smem[];
.visible .entry conv2d_kernel(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 has_bias,
    .param .u32 OC,
    .param .u32 OH,
    .param .u32 OW,
    .param .u32 IC,
    .param .u32 H,
    .param .u32 W,
    .param .u32 KH,
    .param .u32 KW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 in_tile_h,
    .param .u32 in_tile_w
)
{
    .reg .pred %p<32>;
    .reg .b32  %r<64>;
    .reg .b64  %rd<24>;
    .reg .f32  %f<28>;
    mov.u32 %r40, 16;                      // TILE_H
    mov.u32 %r46, 64;                      // TILE_W
    mov.u32 %r41, 256;                     // blockDim.x
    mov.u32 %r0, %tid.x;                   // tid
    div.u32 %r1, %r0, %r40;                // th = tid / 16
    rem.u32 %r2, %r0, %r40;                // tw = tid % 16 (column group)
    mov.u32 %r3, %ctaid.x;                 // 64-wide tile column
    mov.u32 %r4, %ctaid.y;                 // 16-high tile row
    mov.u32 %r5, %ctaid.z;                 // b*OCG + oc_group
    ld.param.u32 %r6, [OC];
    add.u32 %r57, %r6, 3;
    shr.u32 %r57, %r57, 2;                 // OCG = ceil(OC/4)
    rem.u32 %r58, %r5, %r57;               // oc group
    div.u32 %r8, %r5, %r57;                // b
    shl.b32 %r7, %r58, 2;                  // oc_base = oc_group*4
    add.u32 %r59, %r7, 1;
    setp.lt.u32 %p17, %r59, %r6;           // oc lane 1 valid
    add.u32 %r59, %r7, 2;
    setp.lt.u32 %p18, %r59, %r6;           // oc lane 2 valid
    add.u32 %r59, %r7, 3;
    setp.lt.u32 %p19, %r59, %r6;           // oc lane 3 valid
    ld.param.u32 %r9, [OH];
    ld.param.u32 %r10, [OW];
    mad.lo.u32 %r11, %r4, %r40, %r1;       // oh
    mul.lo.u32 %r51, %r2, 4;               // column-group base inside tile
    mad.lo.u32 %r12, %r3, %r46, %r51;      // ow base for 4 outputs
    setp.lt.u32 %p0, %r11, %r9;            // row valid
    add.u32 %r47, %r12, 0;
    add.u32 %r48, %r12, 1;
    add.u32 %r49, %r12, 2;
    add.u32 %r50, %r12, 3;
    setp.lt.u32 %p1, %r47, %r10;
    and.pred  %p13, %p0, %p1;
    setp.lt.u32 %p1, %r48, %r10;
    and.pred  %p14, %p0, %p1;
    setp.lt.u32 %p1, %r49, %r10;
    and.pred  %p15, %p0, %p1;
    setp.lt.u32 %p1, %r50, %r10;
    and.pred  %p16, %p0, %p1;
    ld.param.u32 %r13, [stride_h];
    ld.param.u32 %r14, [stride_w];
    ld.param.u32 %r15, [pad_h];
    ld.param.u32 %r16, [pad_w];
    mul.lo.u32 %r17, %r4, %r40;
    mul.lo.u32 %r17, %r17, %r13;
    sub.s32    %r17, %r17, %r15;           // ih0 signed
    mul.lo.u32 %r18, %r3, %r46;
    mul.lo.u32 %r18, %r18, %r14;
    sub.s32    %r18, %r18, %r16;           // iw0 signed
    ld.param.u32 %r19, [IC];
    ld.param.u32 %r20, [H];
    ld.param.u32 %r21, [W];
    ld.param.u32 %r22, [KH];
    ld.param.u32 %r23, [KW];
    ld.param.u32 %r24, [dil_h];
    ld.param.u32 %r25, [dil_w];
    ld.param.u32 %r26, [in_tile_h];
    ld.param.u32 %r27, [in_tile_w];
    mul.lo.u32 %r28, %r26, %r27;           // tile_size
    mul.lo.u32 %r56, %r19, %r22;
    mul.lo.u32 %r56, %r56, %r23;           // IC*KH*KW (weight oc stride)
    cvt.u64.u32 %rd15, %r56;
    shl.b64     %rd15, %rd15, 2;           // weight oc stride (bytes)
    mul.lo.u32 %r60, %r9, %r10;            // OH*OW
    cvt.u64.u32 %rd16, %r60;
    shl.b64     %rd16, %rd16, 2;           // output oc stride (bytes)
    mov.u64 %rd0, smem;
    mov.f32 %f0, 0f00000000;               // acc oc lane0 col0
    mov.f32 %f1, 0f00000000;               // acc oc lane0 col1
    mov.f32 %f2, 0f00000000;               // acc oc lane0 col2
    mov.f32 %f3, 0f00000000;               // acc oc lane0 col3
    mov.f32 %f8, 0f00000000;               // acc oc lane1 col0
    mov.f32 %f9, 0f00000000;               // acc oc lane1 col1
    mov.f32 %f10, 0f00000000;              // acc oc lane1 col2
    mov.f32 %f11, 0f00000000;              // acc oc lane1 col3
    mov.f32 %f12, 0f00000000;              // acc oc lane2 col0
    mov.f32 %f13, 0f00000000;              // acc oc lane2 col1
    mov.f32 %f14, 0f00000000;              // acc oc lane2 col2
    mov.f32 %f15, 0f00000000;              // acc oc lane2 col3
    mov.f32 %f16, 0f00000000;              // acc oc lane3 col0
    mov.f32 %f17, 0f00000000;              // acc oc lane3 col1
    mov.f32 %f18, 0f00000000;              // acc oc lane3 col2
    mov.f32 %f19, 0f00000000;              // acc oc lane3 col3
    mov.f32 %f21, 0f00000000;              // weight lane1 (stays 0 if oc OOB)
    mov.f32 %f22, 0f00000000;              // weight lane2 (stays 0 if oc OOB)
    mov.f32 %f23, 0f00000000;              // weight lane3 (stays 0 if oc OOB)
    mov.u32 %r29, 0;                       // ic
LOOP_IC:
    setp.ge.u32 %p3, %r29, %r19;
    @%p3 bra STORE;
    mov.u32 %r30, %r0;                     // cooperative idx
LOAD_LOOP:
    setp.ge.u32 %p4, %r30, %r28;
    @%p4 bra LOAD_DONE;
    div.u32 %r31, %r30, %r27;              // ith
    rem.u32 %r32, %r30, %r27;              // itw
    add.s32 %r33, %r17, %r31;              // ih
    add.s32 %r34, %r18, %r32;              // iw
    mov.f32 %f4, 0f00000000;
    setp.lt.s32 %p5, %r33, 0;
    setp.ge.s32 %p6, %r33, %r20;
    or.pred  %p7, %p5, %p6;
    setp.lt.s32 %p8, %r34, 0;
    or.pred  %p7, %p7, %p8;
    setp.ge.s32 %p9, %r34, %r21;
    or.pred  %p7, %p7, %p9;
    @%p7 bra WRITE_SMEM;
    mad.lo.u32 %r35, %r8, %r19, %r29;
    mad.lo.u32 %r35, %r35, %r20, %r33;
    mad.lo.u32 %r35, %r35, %r21, %r34;
    cvt.u64.u32 %rd1, %r35;
    shl.b64     %rd1, %rd1, 2;
    ld.param.u64 %rd2, [in_ptr];
    add.u64     %rd2, %rd2, %rd1;
    ld.global.f32 %f4, [%rd2];
WRITE_SMEM:
    cvt.u64.u32 %rd3, %r30;
    shl.b64     %rd3, %rd3, 2;
    add.u64     %rd4, %rd0, %rd3;
    st.shared.f32 [%rd4], %f4;
    add.u32 %r30, %r30, %r41;
    bra LOAD_LOOP;
LOAD_DONE:
    bar.sync 0;
    mov.u32 %r36, 0;                       // kh
LOOP_KH:
    setp.ge.u32 %p10, %r36, %r22;
    @%p10 bra COMPUTE_DONE;
    mul.lo.u32 %r37, %r1, %r13;            // th*stride_h
    mad.lo.u32 %r37, %r36, %r24, %r37;     // ih_l
    mov.u32 %r38, 0;                       // kw
LOOP_KW:
    setp.ge.u32 %p11, %r38, %r23;
    @%p11 bra NEXT_KH;
    mul.lo.u32 %r39, %r51, %r14;           // (tw*4)*stride_w
    mad.lo.u32 %r39, %r38, %r25, %r39;     // iw_l0
    mad.lo.u32 %r52, %r37, %r27, %r39;     // smem idx0
    add.u32 %r53, %r52, %r14;              // + stride_w
    add.u32 %r54, %r53, %r14;
    add.u32 %r55, %r54, %r14;
    cvt.u64.u32 %rd5, %r52;
    shl.b64     %rd5, %rd5, 2;
    add.u64     %rd5, %rd0, %rd5;
    ld.shared.f32 %f4, [%rd5];
    cvt.u64.u32 %rd6, %r53;
    shl.b64     %rd6, %rd6, 2;
    add.u64     %rd6, %rd0, %rd6;
    ld.shared.f32 %f5, [%rd6];
    cvt.u64.u32 %rd7, %r54;
    shl.b64     %rd7, %rd7, 2;
    add.u64     %rd7, %rd0, %rd7;
    ld.shared.f32 %f6, [%rd7];
    cvt.u64.u32 %rd8, %r55;
    shl.b64     %rd8, %rd8, 2;
    add.u64     %rd8, %rd0, %rd8;
    ld.shared.f32 %f7, [%rd8];
    mad.lo.u32 %r43, %r7, %r19, %r29;      // oc_base*IC + ic
    mad.lo.u32 %r43, %r43, %r22, %r36;     // *KH + kh
    mad.lo.u32 %r43, %r43, %r23, %r38;     // *KW + kw
    cvt.u64.u32 %rd9, %r43;
    shl.b64     %rd9, %rd9, 2;
    ld.param.u64 %rd10, [wt_ptr];
    add.u64     %rd10, %rd10, %rd9;        // &w[oc_base,ic,kh,kw]
    ld.global.f32 %f20, [%rd10];           // weight oc lane 0
    add.u64     %rd11, %rd10, %rd15;
    @%p17 ld.global.f32 %f21, [%rd11];     // weight oc lane 1
    add.u64     %rd12, %rd11, %rd15;
    @%p18 ld.global.f32 %f22, [%rd12];     // weight oc lane 2
    add.u64     %rd13, %rd12, %rd15;
    @%p19 ld.global.f32 %f23, [%rd13];     // weight oc lane 3
    fma.rn.f32 %f0, %f4, %f20, %f0;
    fma.rn.f32 %f1, %f5, %f20, %f1;
    fma.rn.f32 %f2, %f6, %f20, %f2;
    fma.rn.f32 %f3, %f7, %f20, %f3;
    fma.rn.f32 %f8, %f4, %f21, %f8;
    fma.rn.f32 %f9, %f5, %f21, %f9;
    fma.rn.f32 %f10, %f6, %f21, %f10;
    fma.rn.f32 %f11, %f7, %f21, %f11;
    fma.rn.f32 %f12, %f4, %f22, %f12;
    fma.rn.f32 %f13, %f5, %f22, %f13;
    fma.rn.f32 %f14, %f6, %f22, %f14;
    fma.rn.f32 %f15, %f7, %f22, %f15;
    fma.rn.f32 %f16, %f4, %f23, %f16;
    fma.rn.f32 %f17, %f5, %f23, %f17;
    fma.rn.f32 %f18, %f6, %f23, %f18;
    fma.rn.f32 %f19, %f7, %f23, %f19;
    add.u32 %r38, %r38, 1;
    bra LOOP_KW;
NEXT_KH:
    add.u32 %r36, %r36, 1;
    bra LOOP_KH;
COMPUTE_DONE:
    bar.sync 0;
    add.u32 %r29, %r29, 1;
    bra LOOP_IC;
STORE:
    ld.param.u32 %r44, [has_bias];
    setp.eq.u32  %p12, %r44, 0;
    @%p12 bra WRITE;
    cvt.u64.u32 %rd10, %r7;
    shl.b64     %rd10, %rd10, 2;
    ld.param.u64 %rd11, [bias_ptr];
    add.u64     %rd12, %rd11, %rd10;       // &bias[oc_base]
    ld.global.f32 %f24, [%rd12];
    add.f32     %f0, %f0, %f24;
    add.f32     %f1, %f1, %f24;
    add.f32     %f2, %f2, %f24;
    add.f32     %f3, %f3, %f24;
    @%p17 ld.global.f32 %f24, [%rd12+4];
    add.f32     %f8, %f8, %f24;
    add.f32     %f9, %f9, %f24;
    add.f32     %f10, %f10, %f24;
    add.f32     %f11, %f11, %f24;
    @%p18 ld.global.f32 %f24, [%rd12+8];
    add.f32     %f12, %f12, %f24;
    add.f32     %f13, %f13, %f24;
    add.f32     %f14, %f14, %f24;
    add.f32     %f15, %f15, %f24;
    @%p19 ld.global.f32 %f24, [%rd12+12];
    add.f32     %f16, %f16, %f24;
    add.f32     %f17, %f17, %f24;
    add.f32     %f18, %f18, %f24;
    add.f32     %f19, %f19, %f24;
WRITE:
    mad.lo.u32 %r45, %r8, %r6, %r7;        // b*OC + oc_base
    mad.lo.u32 %r45, %r45, %r9, %r11;
    mad.lo.u32 %r45, %r45, %r10, %r12;
    cvt.u64.u32 %rd13, %r45;
    shl.b64     %rd13, %rd13, 2;
    ld.param.u64 %rd14, [out_ptr];
    add.u64     %rd13, %rd13, %rd14;
    @%p13 st.global.f32 [%rd13], %f0;
    @%p14 st.global.f32 [%rd13+4], %f1;
    @%p15 st.global.f32 [%rd13+8], %f2;
    @%p16 st.global.f32 [%rd13+12], %f3;
    and.pred  %p20, %p13, %p17;
    and.pred  %p21, %p14, %p17;
    and.pred  %p22, %p15, %p17;
    and.pred  %p23, %p16, %p17;
    add.u64   %rd17, %rd13, %rd16;
    @%p20 st.global.f32 [%rd17], %f8;
    @%p21 st.global.f32 [%rd17+4], %f9;
    @%p22 st.global.f32 [%rd17+8], %f10;
    @%p23 st.global.f32 [%rd17+12], %f11;
    and.pred  %p24, %p13, %p18;
    and.pred  %p25, %p14, %p18;
    and.pred  %p26, %p15, %p18;
    and.pred  %p27, %p16, %p18;
    add.u64   %rd18, %rd17, %rd16;
    @%p24 st.global.f32 [%rd18], %f12;
    @%p25 st.global.f32 [%rd18+4], %f13;
    @%p26 st.global.f32 [%rd18+8], %f14;
    @%p27 st.global.f32 [%rd18+12], %f15;
    and.pred  %p28, %p13, %p19;
    and.pred  %p29, %p14, %p19;
    and.pred  %p30, %p15, %p19;
    and.pred  %p31, %p16, %p19;
    add.u64   %rd19, %rd18, %rd16;
    @%p28 st.global.f32 [%rd19], %f16;
    @%p29 st.global.f32 [%rd19+4], %f17;
    @%p30 st.global.f32 [%rd19+8], %f18;
    @%p31 st.global.f32 [%rd19+12], %f19;
